use xiom.io;

use xiom.string;
use xiom.convert;
fn main() -> Int {
  let prices: Map[Int,Float64] = Map[Int,Float64].new();
  prices.insert(1, 9.99);
  prices.insert(2, 14.50);
  prices.insert(3, 2.75);

  let features: Map[Str,Bool] = Map[Str,Bool].new();
  features.insert("dark_mode", true);
  features.insert("beta_tester", false);

  match prices.get(2) {
    Some(p) => io.println("Price: " + convert.float_to_string(p));
    None => io.println("Not found");
  }

  match features.get("dark_mode") {
    Some(enabled) => io.println(enabled.to_str());
    None => io.println("Unknown feature");
  }

  return 0;
}
